// Package notices holds the third-party license data shown on the app's
// Third-Party Licenses screen (spec §7). data.json is generated by
// tools/gen-notices; a test fails when go.mod names a module it does not cover.
package notices

import (
	_ "embed"
	"encoding/json"
	"sync"
)

//go:embed data.json
var raw []byte

// Entry is one component: this app, a Go module, a bundled tool, a font.
type Entry struct {
	Name    string
	Version string
	License string
	URL     string
	Kind    string // app | go | js | font | tool | data
	Note    string
	Text    string // the full license text
}

var (
	once sync.Once
	all  []Entry
)

// All returns every component, with its license text.
func All() []Entry {
	once.Do(func() { _ = json.Unmarshal(raw, &all) })
	return all
}

// Find returns the component with the given name.
func Find(name string) (Entry, bool) {
	for _, e := range All() {
		if e.Name == name {
			return e, true
		}
	}
	return Entry{}, false
}
